define(["core/config","tiny_zoomclassroom/options"],function(Config,Options){const toPositiveInt=(value,fallbackValue)=>{const parsed=parseInt(value,10);return Number.isFinite(parsed)&&parsed>0?parsed:fallbackValue;};const handleAction=editor=>{const tool=Options.getTool(editor);if(!tool||!tool.id){window.alert(Options.getErrorMisconfigured(editor));return;}const configuredCourseId=Options.getCourseId(editor),fallbackCourseId=window.M?.cfg?.courseId,courseId=String(configuredCourseId||fallbackCourseId||"0");if(!courseId||courseId==="0"){window.alert(Options.getErrorNoCourse(editor));return;}const width=toPositiveInt(Options.getPopupWidth(editor),1200);const height=toPositiveInt(Options.getPopupHeight(editor),800);const left=Math.max(0,Math.round((window.screen.width-width)/2));const top=Math.max(0,Math.round((window.screen.height-height)/2));const launcherUrl=new URL(`${Config.wwwroot}${Options.getLauncherPath(editor)}`);launcherUrl.searchParams.set("course",courseId);launcherUrl.searchParams.set("id",String(tool.id));launcherUrl.searchParams.set("editorid",editor.id);launcherUrl.searchParams.set("sesskey",Options.getSesskey(editor));const popup=window.open(launcherUrl.toString(),"tiny_zoomclassroom_picker",`popup=yes,width=${width},height=${height},left=${left},top=${top},resizable=yes,scrollbars=yes`);if(popup){popup.focus();return;}window.alert(Options.getErrorPopupBlocked(editor));};return{handleAction:handleAction};});
